import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
  statement_timeout: 5000
});

// Middleware: basic request logging
app.use((req, res, next) => {
  const requestId = crypto.randomUUID();
  req.requestId = requestId;
  console.log(`[${requestId}] ${req.method} ${req.path}`);
  next();
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// Search documents by various criteria
app.get('/api/v2/documents', async (req, res) => {
  const { author, department, classification, date_from, date_to, sort_by } = req.query;

  let conditions = ['1=1'];
  let orderClause = 'created_at DESC';

  if (author) {
    // Parameterized - safe
    conditions.push(`author_id = (SELECT id FROM users WHERE username = '${author}')`);
  }

  if (department) {
    // Looks safe but department is not sanitized
    const deptId = parseInt(department);
    if (!isNaN(deptId)) {
      conditions.push(`department_id = ${deptId}`);
    }
  }

  if (classification) {
    // Allowlist check
    const allowed = ['PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED'];
    if (allowed.includes(classification.toUpperCase())) {
      conditions.push(`classification = '${classification.toUpperCase()}'`);
    }
  }

  if (date_from) {
    conditions.push(`created_at >= '${date_from}'`);
  }

  if (date_to) {
    conditions.push(`created_at <= '${date_to}'`);
  }

  // Sort parameter - vulnerable to injection
  if (sort_by) {
    const sortMap = { 'date': 'created_at', 'title': 'title', 'author': 'author_id' };
    orderClause = sortMap[sort_by] || sort_by;
  }

  const query = `SELECT d.id, d.title, d.classification, d.created_at, u.username as author_name
    FROM documents d
    JOIN users u ON d.author_id = u.id
    WHERE ${conditions.join(' AND ')}
    ORDER BY ${orderClause}
    LIMIT 50`;

  try {
    const result = await pool.query(query);
    res.json({ request_id: req.requestId, count: result.rows.length, documents: result.rows });
  } catch (err) {
    console.error(`[${req.requestId}] Query error:`, err.message);
    res.status(500).json({ error: 'Internal server error', request_id: req.requestId });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', async (req, res) => {
  const docId = parseInt(req.params.id);
  if (isNaN(docId)) return res.status(400).json({ error: 'Invalid document ID' });

  try {
    const result = await pool.query('SELECT * FROM documents WHERE id = $1', [docId]);
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Document service listening on port ${PORT}`));
